//! VSCRATCH: the private-segment instructions.
//!
//! The harness seeds each lane's first eight scratch words, so a load can be
//! checked by the value it returns and a store by what the words became --
//! the simulator and the hardware never put the private segment in the same
//! place, and the hardware swizzles it across lanes besides.
//!
//! Every case states both the destination registers and the lane's eight
//! words, and two lanes are checked, so an instruction that writes the wrong
//! register or reaches another lane's private words fails.

use crate::encoding::*;
use crate::harness::*;
use amdgpu_sim::rdna_processor::Engine;

/// The lanes every case checks.
const CHECK_LANES: [usize; 2] = [0, 7];

/// The values the harness puts in v2..v5, which a store writes to scratch.
const STORE_VALUES: [u32; 4] = [0x1234_5678, 0x9ABC_DEF0, 0x0F0F_0F0F, 0xF0F0_F0F0];

/// One VSCRATCH case. The address is the lane's own private base plus the three
/// parts the format offers, each of which the case states.
pub(crate) struct ScratchCase {
    pub(crate) ioffset: i32,
    /// The VGPR the address comes from, and whether it takes part at all.
    pub(crate) vaddr: u32,
    pub(crate) sve: u32,
    /// The SGPR byte offset, or `SADDR_NULL` for none.
    pub(crate) saddr: u32,
    /// v[6:9] of each checked lane after the instruction.
    pub(crate) vdst: [[u32; 4]; CHECK_LANES.len()],
    /// The eight scratch words each checked lane owns, after the instruction.
    pub(crate) mem: [[u32; 8]; CHECK_LANES.len()],
}

fn run(harness: &Harness, engine: Engine, words: &[u32]) -> ([[u32; 4]; 2], [[u32; 8]; 2]) {
    let mut src = vec![0u32; LANES * harness.src_stride];
    for lane in 0..LANES {
        for (k, value) in STORE_VALUES.iter().enumerate() {
            src[lane * harness.src_stride + k] = value ^ (lane as u32 * 0x0101_0101);
        }
    }
    let uni = vec![0u32; 8];
    let out = harness.run(engine, words, &src, &uni);

    let mut vdst = [[0u32; 4]; 2];
    let mut mem = [[0u32; 8]; 2];
    for (slot, lane) in CHECK_LANES.iter().enumerate() {
        let base = lane * harness.out_stride;
        vdst[slot].copy_from_slice(&out[base..base + 4]);
        mem[slot].copy_from_slice(&out[base + 4..base + 12]);
    }
    (vdst, mem)
}

fn describe(vdst: &[[u32; 4]; 2], mem: &[[u32; 8]; 2]) -> String {
    let mut text = String::new();
    for (slot, lane) in CHECK_LANES.iter().enumerate() {
        text.push_str(&format!(
            " lane {}: vdst [{}] scratch [{}]",
            lane,
            vdst[slot]
                .iter()
                .map(|v| format!("{:08X}", v))
                .collect::<Vec<_>>()
                .join(" "),
            mem[slot]
                .iter()
                .map(|v| format!("{:08X}", v))
                .collect::<Vec<_>>()
                .join(" "),
        ));
    }
    text
}

fn check(op: u32, cases: &[ScratchCase], vdst_reg: u32, vsrc_reg: u32) {
    let harness = Harness::scratch();
    let mut failures = Vec::new();
    for (i, case) in cases.iter().enumerate() {
        // The harness leaves v0 at zero and v1 at 8, and s10 at 4, so a case
        // reaches each of the three address parts by naming them.
        let words = vscratch(
            op,
            vdst_reg,
            vsrc_reg,
            case.vaddr,
            case.saddr,
            case.ioffset,
            case.sve,
        )
        .to_vec();
        for engine in [Engine::Interpreter, Engine::LlvmJit] {
            let (vdst, mem) = run(&harness, engine, &words);
            if vdst == case.vdst && mem == case.mem {
                continue;
            }
            failures.push(format!(
                "  {:<11} case {} (ioffset={} vaddr=v{} sve={} saddr={:#04X})\n    hardware  {}\n    simulator {}",
                engine_name(engine),
                i,
                case.ioffset,
                case.vaddr,
                case.sve,
                case.saddr,
                describe(&case.vdst, &case.mem),
                describe(&vdst, &mem),
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} case-results differ from hardware:\n{}",
        failures.len(),
        cases.len() * 2,
        failures.join("\n"),
    );
}

/// A scratch load: it writes v[6:9] and leaves the private segment alone.
/// Compared bit-exactly; there is nothing approximate about moving bits.
pub(crate) fn check_scratch_load(op: u32, cases: &[ScratchCase]) {
    check(op, cases, 6, 2);
}

/// A scratch store: it writes the private segment from v[2:5] and leaves
/// v[6:9] alone.
pub(crate) fn check_scratch_store(op: u32, cases: &[ScratchCase]) {
    check(op, cases, 6, 2);
}

